package android.hardware.usb;public class UsbInterface {public int id,cls,sub,alt;public UsbEndpoint[] eps;public UsbInterface(int i,int c,int s,UsbEndpoint...e){id=i;cls=c;sub=s;eps=e;}public int getId(){return id;}public int getInterfaceClass(){return cls;}public int getInterfaceSubclass(){return sub;}public int getAlternateSetting(){return alt;}public int getEndpointCount(){return eps.length;}public UsbEndpoint getEndpoint(int i){return eps[i];}}
